add_filter( 'woocommerce_add_to_cart_redirect', 'perfectpixel_remove_add_to_cart_param', 20 );

function perfectpixel_remove_add_to_cart_param( $url ) {
	if ( $url || wp_doing_ajax() || ! isset( $_REQUEST['add-to-cart'] ) ) {
		return $url; // Another redirect is already set, or nothing to clean.
	}
	$current = home_url( wp_unslash( $_SERVER['REQUEST_URI'] ?? '/' ) );
	return remove_query_arg( array( 'add-to-cart', 'quantity', 'variation_id' ), $current );
}
